// Some portions generated by Codex
package org.eclipse.rdf4j.federated.util;

import static org.junit.jupiter.api.Assertions.assertThrows;

import org.eclipse.rdf4j.model.Resource;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.QueryEvaluationException;
import org.junit.jupiter.api.Test;

class FedXBlankNodeTransportTest {
	@Test
	void unsafeIdentityCannotBeReplacedWithDummyIri() {
		var vf = SimpleValueFactory.getInstance();
		assertThrows(QueryEvaluationException.class,
				() -> QueryStringUtil.appendValue(new StringBuilder(), vf.createBNode("known")));
		assertThrows(QueryEvaluationException.class,
				() -> QueryStringUtil.appendValue(new StringBuilder(), vf.createTripleTerm(vf.createBNode("known"),
						vf.createIRI("urn:p"), vf.createLiteral(1))));
	}

	@Test
	void blankNodeGraphCannotBeSilentlyOmittedFromProtocolDataset() {
		var vf = SimpleValueFactory.getInstance();
		assertThrows(QueryEvaluationException.class, () -> FedXUtil.toDataset(new Resource[] {
				vf.createBNode("graph") }));
	}
}
